import gurobipy
from gurobipy import GRB

def solve_problem():
    data = CSVQA_DATA
    tables = data['tables']
    table_map = {t['table_id']: t for t in tables}
    demand_table = table_map['file_0_view_0']
    d_c = {}
    for rec in demand_table['records']:
        cust = rec['values']['customer']
        d_c[cust] = int(rec['values']['demand'])
    supply_table = table_map['file_1_view_0']
    s_s = {}
    for rec in supply_table['records']:
        sup = rec['values']['Unnamed: 0']
        s_s[sup] = int(rec['values']['supply_capacity'])
    cost_table = table_map['file_2_view_0']
    c_sc = {}
    for rec in cost_table['records']:
        sup = rec['values']['Unnamed: 0']
        for cust in d_c:
            if cust not in rec['values']:
                raise ValueError(f'Missing cost for supplier {sup} customer {cust}')
            c_sc[sup, cust] = float(rec['values'][cust])
    S = list(s_s.keys())
    C = list(d_c.keys())
    cost_suppliers = {rec['values']['Unnamed: 0'] for rec in cost_table['records']}
    if set(S) != cost_suppliers:
        missing = set(S) - cost_suppliers
        raise ValueError(f'Suppliers missing in cost matrix: {missing}')
    cost_customers = set()
    for rec in cost_table['records']:
        cost_customers.update(rec['values'].keys() - {'Unnamed: 0'})
    if set(C) != cost_customers:
        missing = set(C) - cost_customers
        raise ValueError(f'Customers missing in cost matrix: {missing}')
    m = gurobipy.Model()
    m.setParam('MIPGap', 1e-06)
    x = m.addVars([(s, c) for s in S for c in C], vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(gurobipy.quicksum((c_sc[s, c] * x[s, c] for s in S for c in C)), GRB.MINIMIZE)
    m.addConstrs((gurobipy.quicksum((x[s, c] for c in C)) <= s_s[s] for s in S), name='')
    m.addConstrs((gurobipy.quicksum((x[s, c] for s in S)) == d_c[c] for c in C), name='')
    m.optimize()
    return m
m = solve_problem()
